import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long factor = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long answer = Long.MIN_VALUE;
        for (int divide = 0; divide < 2; divide++) {
            // before: scored range not yet modified; inside: modifying now; after: modification finished.
            boolean hasB = false, hasM = false, hasA = false;
            long B = 0, M = 0, A = 0;
            for (long x : a) {
                long t = divide == 1 ? x / factor : x * factor;  // Java division truncates toward zero
                long nB = hasB ? Math.max(x, B + x) : x;
                long nM = t;
                if (hasB) nM = Math.max(nM, B + t);
                if (hasM) nM = Math.max(nM, M + t);
                boolean nHasA = hasM || hasA;
                long nA = Long.MIN_VALUE;
                if (hasM) nA = M + x;
                if (hasA) nA = Math.max(nA, A + x);
                B = nB;
                M = nM;
                A = nA;
                hasB = true;
                hasM = true;
                hasA = nHasA;
                answer = Math.max(answer, hasA ? Math.max(M, A) : M);
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, factor := int(nextInt()), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	answer := int64(math.MinInt64)
	for divide := 0; divide < 2; divide++ {
		// before: scored range not yet modified; inside: modifying now; after: modification finished.
		hasB, hasM, hasA := false, false, false
		var B, M, A int64
		for _, x := range a {
			t := x * factor
			if divide == 1 {
				t = x / factor // Go division truncates toward zero
			}
			nB := x
			if hasB {
				nB = max(x, B+x)
			}
			nM := t
			if hasB {
				nM = max(nM, B+t)
			}
			if hasM {
				nM = max(nM, M+t)
			}
			nHasA := hasM || hasA
			nA := int64(math.MinInt64)
			if hasM {
				nA = M + x
			}
			if hasA {
				nA = max(nA, A+x)
			}
			B, M, A = nB, nM, nA
			hasB, hasM, hasA = true, true, nHasA
			if hasA {
				answer = max(answer, M, A)
			} else {
				answer = max(answer, M)
			}
		}
	}
	fmt.Println(answer)
}
